    while not b:
        L = int(input("< Ligne n°= "))
        b = 0 < L <= NL
    b = False
    while not b:
        C = int(input("< colone n°= "))
        b = 0 < C <= NC
    b = False
    while not b:
        S = input("< Séquence: ")
        b = verif(S)
    return NL, NC, L, C, S


def verif(ch):
    ok = True
    i = -1
    while ok and i < len(ch) - 1:
        i += 1
        ok = ch[i] in {"H", "B", "D", "G"}
    return ok


def Robot(NL, NC, L, C, S):
    l = L
    c = C
    i = 0
    ok = False
    while not (ok) and i < len(S):
        if S[i] == "D":
            c += 1
        elif S[i] == "G":
            c -= 1
        elif S[i] == "H":
            l -= 1
        elif S[i] == "B":
            l += 1
        ok = Depacement(i, l, c, NL, NC)
        i += 1
